<script setup lang="ts">
import {ref,onMounted,watch,computed,nextTick} from 'vue'
import type {components} from '../../shared/api'
import type {SessionClient} from '../auth/session'
import {IconPlus,IconX,IconGift,IconCheck,IconPencil,IconBooks,IconCoins} from '@tabler/icons-vue'
import {rewardCategories} from './categories'
import RelationshipShop from './RelationshipShop.vue'
import {useWorkspaceView} from '../workspace/context'
type Reward=components['schemas']['RewardView'];type Grant=components['schemas']['GrantView']
const props=defineProps<{client:SessionClient;ru:boolean;me:components['schemas']['MemberView'];active:boolean;participants:components['schemas']['ParticipantView'][]}>()
const view=useWorkspaceView(),catalogueOpen=ref(false),tab=ref<'shop'|'grants'>('shop'),expandedGrant=ref(''),dialog=ref<HTMLDialogElement|null>(null),shop=ref<InstanceType<typeof RelationshipShop>|null>(null),cover=ref<Reward['cover']>('dinner'),category=ref<Reward['category']>('dates')
const productMode=ref(false),productSelected=ref<components['schemas']['ListingView']|null>(null),productPrice=ref(10),productPublic=ref(true)
const pendingPurchases=computed(()=>grants.value.filter(g=>g.status==='pending_approval'&&g.issuer_id===props.me.id).length)
const manager=computed(()=>props.me.shop_role==='dominant')
const canCreate=computed(()=>manager.value)
const t=(en:string,ru:string)=>props.ru?ru:en
const rewards=ref<Reward[]>([]),grants=ref<Grant[]>([]),busy=ref(false),error=ref(''),editing=ref(false),selected=ref<Reward|null>(null),title=ref(''),description=ref(''),conditions=ref(''),granting=ref<Reward|null>(null),recipient=ref(''),key=ref(crypto.randomUUID())
const recipients=computed(()=>props.participants.filter(p=>view.recipients('rewards.grant').includes(p.id)))
const visibleGrants=computed(()=>grants.value.filter(g=>(!view.selected.value||!g.relation_id||g.relation_id===view.selected.value.id)&&view.pair(g.issuer_id,g.recipient_id)))
const name=(id:string)=>id===props.me.id?props.me.display_name:props.participants.find(p=>p.id===id)?.display_name??t('Participant','Участник')
const label=(s:string)=>({offered:t('Offered','Предложено'),accepted:t('Accepted','Принято'),declined:t('Declined','Отклонено'),delivered:t('Delivered','Вручено'),cancelled:t('Cancelled','Отменено'),pending_approval:t('Awaiting approval','Ждёт разрешения'),redeemed:t('Redeemed','Погашено')}[s]??s)
const time=(s:string)=>new Intl.DateTimeFormat(props.ru?'ru-RU':'en-GB',{timeZone:props.me.timezone,year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',timeZoneName:'short'}).format(new Date(s))
async function load(){rewards.value=await props.client.get('/rewards');grants.value=await props.client.get('/reward-grants')}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'NETWORK_ERROR'}finally{busy.value=false}}
onMounted(()=>run(load));watch(()=>props.active,active=>{if(active)void run(load)});watch(view.revision,()=>{recipient.value='';editing.value=false;granting.value=null;catalogueOpen.value=false;dialog.value?.close();void run(load)});watch(recipient,()=>key.value=crypto.randomUUID())
const dialogOpen=computed(()=>editing.value||!!granting.value||catalogueOpen.value)
watch(dialogOpen,async open=>{await nextTick();if(open&&!dialog.value?.open)dialog.value?.showModal();else if(!open)dialog.value?.close()})
let closing=false
async function close(){if(busy.value||closing)return;closing=true;try{const el=dialog.value;if(el?.open&&!matchMedia('(prefers-reduced-motion: reduce)').matches)await el.animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(12px)'}],{duration:160,easing:'ease-in'}).finished.catch(()=>{});editing.value=false;granting.value=null;catalogueOpen.value=false}finally{closing=false}}
function startGrant(r:Reward){catalogueOpen.value=false;granting.value=r;recipient.value=view.selected.value?.submissive_user_id??'';key.value=crypto.randomUUID()}
function edit(r:Reward|null){productMode.value=false;catalogueOpen.value=false;cover.value=r?.cover??'dinner';category.value=r?.category??'dates';selected.value=r;title.value=r?.title??'';description.value=r?.description??'';conditions.value=r?.conditions??'';editing.value=true}
function newProduct(source?:Reward){edit(source??null);selected.value=null;productSelected.value=null;productMode.value=true;productPrice.value=10;productPublic.value=true}
function editProduct(item:components['schemas']['ListingView']){edit({id:item.product_id!,version_id:item.reward_version_id,revision:item.product_revision??1,title:item.title,description:item.description,conditions:item.conditions,cover:item.cover,category:item.category});productMode.value=true;productSelected.value=item;productPrice.value=item.price;productPublic.value=item.audience_all??false}
async function save(){await run(async()=>{const r=selected.value;const content={title:title.value,description:description.value,conditions:conditions.value,cover:cover.value,category:category.value};if(productMode.value){const item=productSelected.value;const body={...content,price:productPrice.value,audience_all:productPublic.value,...(item?{expected_version:item.product_revision}:{})};if(item)await props.client.patch(`/shop/products/${item.product_id}`,body);else await props.client.post('/shop/products',body);editing.value=false;await load();await shop.value?.load()}else{await props.client.post<Reward>(r?`/rewards/${r.id}/versions`:'/rewards',{...content,...(r?{expected_version:r.revision}:{})});editing.value=false;await load();catalogueOpen.value=true}})}

async function grant(){await run(async()=>{if(!granting.value)return;await props.client.post('/reward-grants',{reward_version_id:granting.value.version_id,recipient_id:recipient.value,idempotency_key:key.value});granting.value=null;await load()})}
async function transition(g:Grant,action:string){await run(async()=>{await props.client.post(`/reward-grants/${g.id}/transitions`,{expected_version:g.revision,action});await load();await shop.value?.load()})}
</script>
<template>
<section id="rewards" class="rewards-market" :class="{'has-shop-balance':tab==='shop'&&view.selected.value?.submissive_user_id===me.id&&['bottom','switch'].includes(me.shop_role??'viewer')}" :aria-label="t('Rewards','Награды')">
 <div class="market-controls"><nav class="market-tabs" :aria-label="t('Reward sections','Разделы наград')"><button :aria-pressed="tab==='shop'" @click="tab='shop'">{{t('Shop','Магазин')}}</button><button :aria-pressed="tab==='grants'" @click="tab='grants'">{{['dominant','switch'].includes(me.shop_role??'viewer')?t('Requests','Запросы'):t('My rewards','Мои награды')}}<small v-if="pendingPurchases"> · {{pendingPurchases}}</small></button></nav><button v-if="manager" class="icon-button" :aria-label="t('Reward library','Библиотека наград')" :title="t('Reward library','Библиотека наград')" @click="catalogueOpen=true"><IconBooks :size="20" /></button></div>
 <p v-if="error&&!dialogOpen" role="alert">{{error}}</p>
 <RelationshipShop ref="shop" v-show="tab==='shop'" :me="me" :participants="participants" :recipient-name="view.selected.value?name(view.selected.value.submissive_user_id):''" :paused="me.paused" :client="client" :ru="ru" :rewards="rewards" :active="active&&tab==='shop'" @changed="run(load)" @create="newProduct" @edit="editProduct" />
 <div v-if="tab==='grants'" class="market-grants">
  <p v-if="!visibleGrants.length" class="muted">{{t('No rewards here yet.','Здесь пока нет наград.')}}</p>
  <article v-for="g in visibleGrants" :key="g.id" class="market-grant"><button class="grant-toggle" :aria-expanded="expandedGrant===g.id" @click="expandedGrant=expandedGrant===g.id?'':g.id"><img :src="'/shop/'+g.cover+'.png'" alt="" loading="lazy"><span><strong>{{g.title}}</strong><small>{{name(g.issuer_id)}} → {{name(g.recipient_id)}}</small></span><small>{{label(g.status)}}</small></button><div v-if="expandedGrant===g.id" class="grant-content"><p>{{g.description}}</p><p v-if="g.conditions">{{g.conditions}}</p><small v-if="g.purchase_amount" class="muted">{{g.purchase_amount}} {{t('coins','монет')}} · {{g.status==='pending_approval'?t('Reserved','В резерве'):g.status==='declined'||g.status==='cancelled'?t('Reservation released','Резерв снят'):t('Charged','Списано')}}</small><small class="muted">{{g.source==='purchase'?t('Purchase','Покупка'):g.occurrence_id?t('Completed ritual','Выполненный ритуал'):t('Manual grant','Ручная выдача')}}</small><div class="row-actions"><template v-if="g.source==='purchase'"><button v-if="g.issuer_id===me.id&&g.status==='pending_approval'" :disabled="busy||me.paused" @click="transition(g,'approve')"><IconCheck :size="18"/>{{t('Approve','Разрешить')}}</button><button v-if="g.issuer_id===me.id&&g.status==='pending_approval'" :disabled="busy" @click="transition(g,'reject')">{{t('Reject','Отказать')}}</button><button v-if="g.recipient_id===me.id&&g.status==='pending_approval'" :disabled="busy" @click="transition(g,'cancel')">{{t('Withdraw request','Отозвать запрос')}}</button><button v-if="g.status==='accepted'" :disabled="busy" @click="transition(g,'redeem')"><IconCheck :size="18"/>{{t('Redeem after completion','Погасить после выполнения')}}</button></template><button v-if="g.recipient_id===me.id&&g.status==='offered'" :disabled="busy" @click="transition(g,'accept')"><IconCheck :size="18" />{{t('Accept reward','Принять награду')}}</button><button v-if="g.recipient_id===me.id&&g.status==='offered'" :disabled="busy" @click="transition(g,'decline')">{{t('Decline','Отклонить')}}</button><button v-if="g.issuer_id===me.id&&g.status==='accepted'&&g.source!=='purchase'" :disabled="busy||me.paused" @click="transition(g,'deliver')">{{t('Mark delivered','Отметить вручение')}}</button><button v-if="g.issuer_id===me.id&&g.source!=='purchase'&&['offered','accepted'].includes(g.status)" :disabled="busy||me.paused" @click="transition(g,'cancel')">{{t('Cancel reward','Отменить награду')}}</button></div><details><summary>{{t('Grant history','История выдачи')}}</summary><p v-for="h in g.history" :key="h.revision">{{label(h.status)}} · {{time(h.created_at)}}</p></details></div></article>
 </div>
 <dialog ref="dialog" class="market-dialog" :class="{'market-editor':editing}" :aria-label="editing?(productMode?t('Product editor','Редактор товара'):t('Reward editor','Редактор награды')):granting?t('Offer reward','Выдать награду'):t('Reward library','Библиотека наград')" @cancel.prevent="close"><header><h3>{{editing?(productMode?(selected?t('Edit product','Редактирование товара'):t('New product','Новый товар')):(selected?t('Edit reward','Редактирование награды'):t('New reward','Новая награда'))):granting?t('Offer reward','Выдать награду'):t('Reward library','Библиотека наград')}}</h3><button class="icon-button" :aria-label="t('Close','Закрыть')" :disabled="busy" @click="close"><IconX :size="20" /></button></header><p v-if="error" role="alert">{{error}}</p>
 <form v-if="editing" @submit.prevent="save"><label>{{t('Title','Название')}}<input v-model="title" required maxlength="200" autofocus></label><label>{{t('Description','Описание')}}<textarea v-model="description" required maxlength="10000" rows="3" /></label><label>{{t('Conditions','Условия')}}<textarea v-model="conditions" maxlength="10000" rows="2" /></label><img v-if="cover?.startsWith('reward-')" :src="'/shop/'+cover+'.png'" alt="" class="fixture-cover-preview"><fieldset class="reward-cover-picker"><legend>{{t('Cover','Обложка')}}</legend><label v-for="c in (['dinner','breakfast','cinema','walk'] as const)" :key="c"><input v-model="cover" type="radio" :value="c" :aria-label="({dinner:t('Dinner','Ужин'),breakfast:t('Breakfast','Завтрак'),cinema:t('Cinema','Кино'),walk:t('Walk','Прогулка')})[c]"><img :src="'/shop/'+c+'.png'" alt=""></label></fieldset><label>{{t('Shelf','Полка магазина')}}<select v-model="category"><option v-for="c in rewardCategories" :key="c.id" :value="c.id">{{t(c.en,c.ru)}}</option></select></label><template v-if="productMode"><label>{{t('Price in coins','Цена в монетах')}}<input v-model.number="productPrice" type="number" min="1" max="1000000000" required></label><label class="shop-relation-switch"><input v-model="productPublic" type="checkbox">{{t('Available to everyone','Доступен всем')}}</label></template><p v-if="selected&&!productMode" class="muted">{{t('A new version does not change existing shop items or granted rewards.','Новая версия не меняет существующие лоты и выданные награды.')}}</p><footer><button :disabled="busy||me.paused||!title.trim()||!description.trim()"><IconCheck :size="18" />{{productMode?t('Save product','Сохранить товар'):t('Save reward','Сохранить награду')}}</button></footer></form>
 <form v-else-if="granting" @submit.prevent="grant"><h4>{{granting.title}}</h4><label>{{t('Recipient','Получатель')}}<select v-model="recipient" required><option value="" disabled>{{t('Choose participant','Выберите участника')}}</option><option v-for="p in recipients" :key="p.id" :value="p.id">{{p.display_name}}</option></select></label><footer><button :disabled="busy||me.paused||!recipient">{{t('Confirm reward offer','Подтвердить выдачу')}}</button></footer></form>
 <template v-else-if="catalogueOpen"><button :disabled="busy||!canCreate||me.paused" @click="edit(null)"><IconPlus :size="18" />{{t('New reward','Новая награда')}}</button><p v-if="!rewards.length" class="muted">{{t('No reward definitions yet.','Пока нет наград.')}}</p><article v-for="r in rewards" :key="r.id" class="library-product"><img :src="'/shop/'+r.cover+'.png'" alt=""><div><h4>{{r.title}}</h4><small>{{r.description}}</small><div class="row-actions"><button :disabled="busy||me.paused" :aria-label="t('Edit: ','Редактировать: ')+r.title" @click="edit(r)"><IconPencil :size="18" /></button><button :disabled="busy||!canCreate" @click="close();shop?.openAdd(r.version_id)"><IconCoins :size="18" />{{t('To shop','В магазин')}}</button><button v-if="recipients.length" :disabled="busy||me.paused" :aria-label="t('Offer: ','Выдать: ')+r.title" @click="startGrant(r)"><IconGift :size="18" /></button></div></div></article></template>
 </dialog>
</section>
</template>
